import { createRoot } from "react-dom/client";
import { useEffect, useMemo, useState, useRef } from "react";
import { CompatibleThemePreview, getCompatibleThemeEditingSurface } from "../../src/components/CompatibleThemePreview.tsx";
import { StylePreviewContent } from "../../src/components/StylePreviewContent.tsx";
import { useStylePreviewPolicy } from "../../src/preview/useStylePreviewPolicy.ts";
import { useGeneralSettings } from "../../src/generalSettings.ts";
import { loadSceneSettings, saveSceneSettings } from "../../src/components/sceneSettings.ts";
import { DEFAULT_STYLE_PREVIEW_POLICY, selectStylePreviewEvents, projectSourcePreviewFact } from "../../src/preview/stylePreviewPolicy.ts";
import { createBuiltinNativeTheme } from "../../src/themes/nativeBuiltinThemes.ts";
import { createCompatibleThemeModeAdapter } from "../../src/themes/themeModeAdapters.ts";
import { getOriginalSamples } from "../../src/compat/laplace/renderer/samples.ts";
import type { StylePreviewSnapshot, PreviewFrame } from "../../src/preview/stylePreviewState.ts";
import type { ThemeMode } from "../../src/themes/themeTypes.ts";
import "../../src/compat/blivechat/register.tsx";
import "../../src/compat/openlive/register.tsx";
import "../../src/compat/laplace/register.tsx";
import "../../src/App.css";
const q = new URLSearchParams(location.search), mode = (q.get('mode') || 'native') as ThemeMode;
const accentCss='[data-compatible-event-id],.event[data-event-id],.event-row-slot{outline:2px solid rgb(17, 99, 177)!important}';
const role = q.get('role') || 'editor', channel = new BroadcastChannel(q.get('session') || 'preview-policy-fixture');
const now = Date.now(), amounts = [29.99,49.99,50,60,100];
const events = amounts.map((amount,index) => ({ id:`gift-${index}`, roomId:1, ts:now, msgType:1, user:{uid:'1',uname:'验收用户'}, gift:{id:1,name:`金额${amount}`,count:1,price:amount*1000,total:amount*1000,coinType:'gold' as const,priceRmb:amount,totalRmb:amount,paymentRmb:amount} }));
const giftSample = getOriginalSamples('static').find(e=>e.type==='gift')!;
const laplace = amounts.map((amount,index)=>({...giftSample,id:`gift-${index}`,origin:1,originIdx:index,timestamp:now,timestampNormalized:now,giftName:`金额${amount}`,giftAmount:1,priceNormalized:amount,coinType:'gold'}));
function App(){
 const [all,setAll]=useState(false),[motion,setMotion]=useState<'static'|'design'|'simulation'>('static'),[restart,setRestart]=useState(0),[capacity,setCapacity]=useState(2),[threshold,setThreshold]=useState(50),[frame,setFrame]=useState<PreviewFrame>({epoch:0}),[received,setReceived]=useState<StylePreviewSnapshot>();
 const [accent,setAccent]=useState(false);
 const baseDocument=useMemo(()=>mode==='native'?createBuiltinNativeTheme('native-default'):createCompatibleThemeModeAdapter(mode).createBuiltinTheme(),[]);
 const document=useMemo(()=>({...baseDocument,styles:{...baseDocument.styles,customCss:accent?accentCss:''}}),[baseDocument,accent]);
 const policy=useStylePreviewPolicy();
 useEffect(()=>{if(role!=='editor')return;useGeneralSettings.setState({eventWindowCapacity:capacity,stickyEvents:{...DEFAULT_STYLE_PREVIEW_POLICY.stickySettings,enabled:true,obsEnabled:true,giftThreshold:50,maxCount:2},eventDisplayPreferences:{...DEFAULT_STYLE_PREVIEW_POLICY.displayPreferences,eventAnimationPreset:'none'},eventExpiry:{enabled:false,seconds:10}});saveSceneSettings({...loadSceneSettings(),giftThreshold:threshold});},[capacity,threshold]);
 const retired=useRef({epoch:'',ids:new Set<string>()});const epoch=motion+':'+restart;if(retired.current.epoch!==epoch)retired.current={epoch,ids:new Set()};
 const selected=selectStylePreviewEvents(mode==='laplace'?laplace.map(e=>projectSourcePreviewFact(e,'laplace')):events,policy,{target:'obs',mode:motion,displayAll:all,now},retired.current.ids);retired.current.ids=selected.retiredMainIds;
 const mainKey=JSON.stringify(selected.events.map(e=>e.id));
 const input=useMemo(()=>({epoch:restart,now,events:laplace,restart,mainEventIds:JSON.parse(mainKey)}),[restart,mainKey]);
 const content:any=mode==='native'?{previewCss:accent?accentCss:'',context:'obs',mode:all?'all':'current',events,eventStyleSettings:document.settings,displayPreferences:policy.displayPreferences,eventFontSize:20,windowEventFontSize:20,stickySettings:policy.stickySettings,previewPolicy:policy,previewMotion:motion,previewNow:now,previewMainEventIds:selected.events.map(e=>e.id),previewScheme:'light'}:{document,previewPolicy:policy,previewMode:motion,previewPlaying:false,previewSpeed:1,previewRestartKey:restart,displayAll:all,previewTarget:'obs',previewScheme:'light',previewBackground:'transparent',width:440};
 const snapshot={kind:mode==='native'?'native':'compatible',ownerId:'fixture',revision:restart+threshold+capacity+(all?1:0),palette:'pine',scheme:'light',width:440,height:600,content,frame:mode==='laplace'?input:frame} as StylePreviewSnapshot;
 useEffect(()=>{if(role==='editor'){channel.postMessage(snapshot);const receive=()=>channel.postMessage(snapshot);channel.addEventListener('message',receive);return()=>channel.removeEventListener('message',receive);} },[JSON.stringify(snapshot)]);
 useEffect(()=>{if(role==='editor')return;const receive=(e:MessageEvent)=>{if(e.data?.kind)setReceived(e.data)};channel.addEventListener('message',receive);channel.postMessage('request');return()=>channel.removeEventListener('message',receive)},[]);
 (window as any).previewFixture={snapshot,configure:(next:any)=>{if(next.accent!==undefined)setAccent(next.accent);if(next.all!==undefined)setAll(next.all);if(next.motion)setMotion(next.motion);if(next.capacity)setCapacity(next.capacity);if(next.threshold!==undefined)setThreshold(next.threshold);if(next.restart)setRestart(x=>x+1)}};
 const surface=getCompatibleThemeEditingSurface(mode);
 return <><div>{role} / {mode} / {motion} / {all?'显示全部部件':'当前设置'}</div><main style={{width:"min(440px, 100vw)",height:600}}>{role!=='editor'?received&&<StylePreviewContent state={received} transparent={role==='web'}/>:mode==='native'?<StylePreviewContent state={snapshot}/>:surface&&<CompatibleThemePreview {...content} capability={surface.capability} renderer={surface.renderer} composeCss={surface.composeCss} previewFrame={mode==='laplace'?input:undefined} onPreviewFrame={setFrame}/>}</main></>;
}
createRoot(document.getElementById('root')!).render(<App/>);
import "../../src/components/nativeThemeEditor.css";
